"""Apply the Philadelphia research template to the shared Chicago narrative."""
from pathlib import Path
import json,html,shutil
from publication_content import ROOT,content
esc=html.escape
EXPLORER='''<div class="explorer" aria-labelledby="explorer-title"><h3 id="explorer-title">The same neighborhoods before and after</h3><label for="event-select">Choose a business event</label><select id="event-select" disabled><option>Loading events…</option></select><p>Shading shows modeled one-way walking minutes to the nearest eligible larger grocery outlet. Both panels use the same origins, street network and scale.</p><figure><a id="map-full" href="outputs/figures/explorer/walmart_kenwood.png"><img id="event-map" src="outputs/figures/explorer/walmart_kenwood.png" alt="Kenwood before and after tract access maps"></a><figcaption id="map-summary" aria-live="polite"></figcaption></figure><p class="mini"><a id="map-svg" href="outputs/figures/explorer/walmart_kenwood.svg" download>Download this Matplotlib figure as SVG</a></p><details><summary>Tract values for this comparison</summary><div class="table-scroll"><table><thead><tr><th>Tract GEOID</th><th>Before minutes</th><th>After minutes</th></tr></thead><tbody id="tract-values"></tbody></table></div></details><noscript><p>The selector requires JavaScript. Kenwood is shown above; all six events appear in the figures and downloadable data.</p></noscript></div>'''
def block(b):
    if 'paragraph' in b:return '<p>'+esc(b['paragraph'])+'</p>'
    if 'figure' in b:
        n=b['figure'];return f'<figure class="wide"><a href="outputs/figures/{n}.png" title="Open full-size figure"><img src="outputs/figures/{n}.png" alt="{esc(b["caption"])}" loading="lazy"></a><figcaption>{esc(b["caption"])} <a href="outputs/figures/{n}.svg" download>SVG ↓</a></figcaption></figure>'
    t=b['table'];return '<div class="table-scroll"><table><thead><tr>'+''.join('<th scope="col">'+esc(x)+'</th>' for x in t['headers'])+'</tr></thead><tbody>'+''.join('<tr>'+''.join(('<th scope="row">' if i==0 else '<td>')+esc(str(x))+('</th>' if i==0 else '</td>') for i,x in enumerate(row))+'</tr>' for row in t['rows'])+'</tbody></table></div>'
